#!/usr/bin/env bash
set -euo pipefail

PAGE="${1:?Usage: write-release-download-page.sh <index.html path>}"
: "${APP_NAME:?}" "${VERSION:?}" "${BUILD:?}" "${RELEASED:?}" "${MINIMUM_SYSTEM:?}"
: "${DMG_NAME:?}" "${DMG_BYTES:?}" "${DMG_SHA256:?}"
: "${ARCHIVE_NAME:?}" "${ARCHIVE_BYTES:?}" "${ARCHIVE_SHA256:?}" "${FEED_NOTE:?}" "${ICON_SOURCE:?}" "${PLATFORM_NOTE:?}"
[[ -f "$ICON_SOURCE" ]] || { printf 'The app icon %s is missing.\n' "$ICON_SOURCE" >&2; exit 1; }

megabytes() { awk -v bytes="$1" 'BEGIN { printf "%.1f MB", bytes / 1000000 }'; }
DMG_SIZE="$(megabytes "$DMG_BYTES")"
ARCHIVE_SIZE="$(megabytes "$ARCHIVE_BYTES")"

/usr/bin/sips -Z 256 -s format png "$ICON_SOURCE" --out "$(dirname "$PAGE")/icon.png" >/dev/null

INSTALL_SECTION=""
if [[ -n "${INSTALL_STEPS:-}" ]]; then
  step_number=0
  steps=""
  while IFS= read -r step; do
    [[ -n "$step" ]] || continue
    step_number=$((step_number + 1))
    steps+="<li class=\"flex gap-3 text-sm leading-relaxed text-muted-foreground\"><span class=\"flex size-6 shrink-0 items-center justify-center rounded-full border bg-secondary text-xs font-medium text-secondary-foreground\">${step_number}</span><span class=\"text-foreground\">${step}</span></li>"
  done <<< "$INSTALL_STEPS"
  INSTALL_SECTION="<section class=\"mt-12 overflow-hidden rounded-2xl border bg-card text-card-foreground\"><h2 class=\"border-b px-5 py-3 text-sm font-medium\">Install</h2><ol class=\"space-y-4 px-5 py-4\">${steps}</ol></section>"
fi

PAGE_CSS="$(cat <<'PAGE_CSS'
